INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(68963107, 'Boo Koo', '书之精灵', 'ブークー', 'Normal Monster', 'Spellcaster', 'DARK', 2, 650, 500, '书形的魔法师。写有各种各样的魔法。'),
(27923575, 'Boo-Boo Game', '蠢贼游戏', 'ブービーゲーム', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己要受到战斗伤害的伤害计算时才能发动。那次战斗发生的对自己的战斗伤害变成0。 ②：盖放的这张卡被对方的效果破坏送去墓地的场合，以「蠢贼游戏」以外的自己墓地最多2张通常陷阱卡为对象才能发动。那些卡在自己场上盖放。这个效果盖放的卡在盖放的回合也能发动。'),
(24425055, 'Booby Trap E', '诡雷陷阱E', 'ブービートラップE', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：丢弃1张手卡才能发动。选自己的手卡·墓地1张永续陷阱卡在自己场上盖放。这个效果盖放的卡在盖放的回合也能发动。'),
(96704974, 'Boogie Trap', '鬼雷弦阱', 'ブーギートラップ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：丢弃2张手卡，以自己墓地1张陷阱卡为对象才能发动。那张卡在自己场上盖放。这个效果盖放的卡在盖放的回合也能发动。'),
(35480699, 'Book of Eclipse', '日全食之书', '皆既日蝕の書', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：场上的表侧表示怪兽全部变成里侧守备表示。这个回合的结束阶段，对方场上的里侧守备表示怪兽全部变成表侧守备表示，那之后，对方从卡组抽出这个效果变成表侧守备表示的怪兽的数量。'),
(2204140, 'Book of Life', '生者之书－禁断的咒术－', '生者の書－禁断の呪術－', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只不死族怪兽和对方墓地1只怪兽为对象才能发动。那只自己的不死族怪兽特殊召唤。那只对方怪兽除外。'),
(31834488, 'Book of Lunar Eclipse', '月全食之书', '皆既月蝕の書', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：丢弃1张手卡，以场上2只表侧表示怪兽为对象才能发动。那些怪兽变成里侧守备表示。'),
(14087893, 'Book of Moon', '月之书', '月の書', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示。'),
(91595718, 'Book of Secret Arts', '秘术之书', '秘術の書', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '魔法师族怪兽才能装备。装备怪兽的攻击力·守备力上升300。'),
(38699854, 'Book of Taiyou', '太阳之书', '太陽の書', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1只里侧表示怪兽为对象才能发动。那只里侧表示怪兽变成表侧攻击表示。'),
(14839621, 'Boompoline!!', '嘣床', 'ドカンポリン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '指定没有使用的怪兽区域1处才能把这张卡发动。 ①：指定的区域有效果怪兽特殊召唤的场合发动。那个区域存在的怪兽和这张卡共2张回到持有者手卡。'),
(12986778, 'Boon of the Meklord Emperor', '机皇帝的赐与', '機皇帝の賜与', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '场上表侧表示存在的怪兽只有名字带有「机皇」的怪兽2只的场合才能发动。从自己卡组抽2张卡。这张卡发动的回合，自己不能进行战斗阶段。'),
(80457744, 'Boost Warrior', '推进战士', 'ブースト・ウォリアー', 'Effect Monster', 'Warrior', 'FIRE', 1, 300, 200, '①：自己场上有调整存在的场合，这张卡可以从手卡守备表示特殊召唤。 ②：只要这张卡在怪兽区域存在，自己场上的战士族怪兽的攻击力上升300。'),
(12023931, 'Booster Dragon', '助瞄龙', 'ブースター・ドラゴン', 'Link Monster', 'Dragon', 'DARK', NULL, 1900, NULL, '「弹丸」怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，以场上1只其他的表侧表示怪兽为对象才能发动（对方不能对应这个效果的发动把卡的效果发动）。那只怪兽的攻击力·守备力上升500。 ②：连接召唤的这张卡被战斗·效果破坏送去墓地的场合，以自己墓地1只其他的龙族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(36668118, 'Boot Sector Launch', '轮转导引扇区', 'リボルブート・セクター', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：场上的「弹丸」怪兽的攻击力·守备力上升300。 ②：可以从以下效果选择1个发动。 ●从手卡把最多2只「弹丸」怪兽守备表示特殊召唤（同名卡最多1张）。 ●对方场上的怪兽数量比自己场上的怪兽多的场合，把最多有那个相差数量的「弹丸」怪兽从自己墓地守备表示特殊召唤（同名卡最多1张）。'),
(70950698, 'Boot Staggered', '引导交错鹿', 'ブート・スタッガード', 'Effect Monster', 'Cyberse', 'LIGHT', 5, 2300, 500, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上有电子界族怪兽召唤时才能发动。这张卡从手卡特殊召唤。 ②：这张卡给与对方战斗伤害时才能发动。在自己场上把1只「引导鹿衍生物」（电子界族·地·1星·攻/守0）特殊召唤。'),
(36322312, 'Boot-Up Admiral - Destroyer Dynamo', '起动提督 破坏旋转者', '起動提督デストロイリボルバー', 'Effect Monster', 'Machine', 'EARTH', 8, 2500, 2500, '这张卡不能通常召唤。从手卡以及自己场上的表侧表示的卡之中把2张「零件」怪兽卡送去墓地的场合才能特殊召唤。 ①：只要自己场上有「零件」怪兽或者当作装备卡使用的「零件」怪兽存在，这张卡不会被战斗·效果破坏。 ②：1回合1次，以这张卡以外的场上1张卡为对象才能发动。那张卡破坏。'),
(938717, 'Boot-Up Corporal - Command Dynamo', '起动兵长 指挥旋转者', '起動兵長コマンドリボルバー', 'Effect Monster', 'Machine', 'EARTH', 4, NULL, 2000, '这个卡名的①的效果1回合只能使用1次。 ①：以自己的场上·墓地最多2只机械族「零件」怪兽为对象才能发动（同名卡最多1张）。这张卡从手卡特殊召唤。那之后，作为对象的自己的「零件」怪兽当作装备卡使用给这张卡装备。 ②：这张卡的攻击力上升这张卡的效果装备的怪兽数量×1000。'),
(63717421, 'Boot-Up Order - Gear Charge', '起动指令 齿轮突击', '起動指令 ギア・チャージ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：这张卡的发动时，可以以自己场上的当作装备卡使用的「零件」怪兽卡任意数量为对象。那个场合，那些卡特殊召唤。 ②：丢弃1张手卡才能发动。从卡组把1只「起动提督 破坏旋转者」加入手卡。'),
(9715126, 'Boot-Up Order - Gear Force', '起动指令 齿轮武力', '起動指令 ギア・フォース', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的怪兽只有机械族怪兽的场合，自己或者对方的怪兽的攻击宣言时才能发动。选最多有自己场上的机械族怪兽数量的对方场上的攻击表示怪兽破坏。'),
(13316346, 'Boot-Up Soldier - Dread Dynamo', '起动士兵 死亡旋转者', '起動兵士デッドリボルバー', 'Effect Monster', 'Machine', 'EARTH', 4, NULL, 2000, '只要自己场上有名字带有「零件」的怪兽表侧表示存在，这张卡的攻击力上升2000。'),
(96699830, 'Born from Draconis', '降生自天龙座', 'ボーン・フロム・ドラコニス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能用这张卡的效果以外把怪兽特殊召唤。 ①：从自己墓地以及自己场上的表侧表示怪兽之中把机械族·光属性怪兽全部除外才能发动。从手卡把1只6星以上的机械族·光属性怪兽无视召唤条件特殊召唤。这个效果特殊召唤的怪兽的攻击力·守备力变成因为这张卡发动而除外的怪兽数量×500，不受自身以外的卡的效果影响。'),
(62753201, 'Borrel Cooling', '枪管冷却', 'ヴァレル・レフリジェレーション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只「弹丸」怪兽解放，以自己场上1只「枪管」连接怪兽为对象才能把这张卡发动。这张卡当作装备卡使用给那只怪兽装备。装备怪兽得到以下效果。 ●1回合1次，以自己场上1只怪兽为对象才能发动。这个回合，那只怪兽不会被战斗·效果破坏。这个效果在对方回合也能发动。'),
(87607094, 'Borrel Reboot', '枪管重启', 'ヴァレル・リブート', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这张卡也能把基本分支付一半从手卡发动。 ①：自己场上有「弹丸」怪兽或「枪管」怪兽存在，对方把魔法·陷阱卡发动时才能发动。那个发动无效，那张卡直接盖放。这个效果盖放的卡在这个回合不能发动。'),
(6556178, 'Borrel Regenerator', '枪管再上膛', 'ヴァレル・リロード', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只「弹丸」怪兽为对象才能把这张卡发动。那只怪兽特殊召唤，把这张卡装备。这张卡从场上离开时那只怪兽除外。 ②：装备怪兽被破坏让这张卡被送去墓地的场合才能发动。自己抽1张。'),
(30131474, 'Borrel Supplier', '枪管供给点', 'ヴァレル・サプライヤー', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上有「枪管」连接怪兽存在的场合，自己·对方的准备阶段以自己墓地1只「弹丸」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段破坏。'),
(67288539, 'Borrelcode Dragon', '枪管代码龙', 'ヴァレルコード・ドラゴン', 'Link Monster', 'Dragon', 'DARK', NULL, 2500, NULL, '效果怪兽2只以上 这个卡名的②③的效果1回合各能使用1次。 ①：连接怪兽所连接区的这张卡不会被效果破坏。 ②：怪兽3只为素材作连接召唤的这张卡在和对方怪兽进行战斗的伤害步骤开始时才能发动。场上的怪兽全部破坏。 ③：把墓地的这张卡除外才能发动。选场上1只攻击力3000以上的暗属性怪兽除外，从自己的额外卡组·墓地选1只「拓扑」怪兽特殊召唤。'),
(98630720, 'Borrelend Dragon', '枪管终极龙', 'ヴァレルエンド・ドラゴン', 'Link Monster', 'Dragon', 'DARK', NULL, 3500, NULL, '效果怪兽3只以上 这个卡名的③的效果1回合只能使用1次。 ①：场上的这张卡不会被战斗·效果破坏，双方不能把这张卡作为怪兽的效果的对象。 ②：这张卡可以向对方怪兽全部各作1次攻击。 ③：自己·对方回合，以场上1只效果怪兽和自己墓地1只「弹丸」怪兽为对象才能发动（对方不能对应这个效果的发动把卡的效果发动）。那只场上的怪兽的效果无效，那只墓地的怪兽特殊召唤。'),
(68987122, 'Borrelguard Dragon', '枪管守卫龙', 'ヴァレルガード・ドラゴン', 'Link Monster', 'Dragon', 'DARK', NULL, 3000, NULL, '效果怪兽3只以上 ①：场上的这张卡不会被效果破坏。 ②：1回合1次，把自己的魔法与陷阱区域1张卡送去墓地才能发动。把这个回合被破坏送去自己或对方的墓地的1只怪兽在自己场上特殊召唤。这个效果特殊召唤的怪兽的效果无效化。 ③：自己·对方回合1次，以场上1只怪兽为对象才能发动（对方不能对应这个发动把卡的效果发动）。那只怪兽变成表侧守备表示。'),
(31833038, 'Borreload Dragon', '枪管上膛龙', 'ヴァレルロード・ドラゴン', 'Link Monster', 'Dragon', 'DARK', NULL, 3000, NULL, '效果怪兽3只以上 ①：双方不能把场上的这张卡作为怪兽的效果的对象。 ②：自己·对方回合1次，以场上1只表侧表示怪兽为对象才能发动（对方不能对应这个效果的发动把卡的效果发动）。那只怪兽的攻击力·守备力下降500。 ③：这张卡向对方怪兽攻击的伤害步骤开始时才能发动。那只对方怪兽在这张卡所连接区放置得到控制权。这个效果得到的怪兽在下个回合的结束阶段送去墓地。'),
(6247535, 'Borreload eXcharge Dragon', '枪管上膛超充龙', 'ヴァレルロード・X・ドラゴン', 'XYZ Monster', 'Dragon', 'DARK', 4, 3000, 2500, '龙族·暗属性4星怪兽×2 ①：超量召唤的这张卡不会成为其他怪兽的效果的对象。 ②：1回合1次，把这张卡1个超量素材取除，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力·守备力下降600。那之后，可以从自己墓地选1只「枪管」怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段除外。这个效果的发动后，直到回合结束时自己不能把怪兽特殊召唤，不能直接攻击。'),
(84464389, 'Borreload Fatalflare Dragon', '枪管上膛绝焰龙', 'ヴァレルロード・FF・ドラゴン', 'Fusion Monster', 'Dragon', 'DARK', 8, 2500, 2000, '暗属性连接怪兽＋暗属性怪兽 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡融合召唤的场合才能发动。从卡组把1只「弹丸」怪兽加入手卡。 ②：以自己场上1只暗属性怪兽为对象才能发动。自己的墓地·除外状态的1只暗属性连接怪兽当作攻击力上升500的装备魔法卡使用给作为对象的怪兽装备。 ③：这张卡作为连接素材送去墓地的场合，以场上1张卡为对象才能发动。那张卡破坏。'),
(92892239, 'Borreload Furious Dragon', '枪管上膛暴怒龙', 'ヴァレルロード・F・ドラゴン', 'Fusion Monster', 'Dragon', 'DARK', 8, 3000, 2500, '龙族·暗属性怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，以自己场上1只怪兽和对方场上1张卡为对象才能发动。那些卡破坏。 ②：把墓地的这张卡除外，以自己墓地1只暗属性连接怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不能把效果发动。'),
(7987191, 'Borreload Riot Dragon', '枪管上膛镇暴龙', 'ヴァレルロード・R・ドラゴン', 'Ritual Effect Monster', 'Dragon', 'DARK', 8, 3000, 2500, '「重型扳机」降临。这个卡名的①②的效果1回合各能使用1次。 ①：对方把怪兽特殊召唤之际才能发动。那次特殊召唤无效，那些怪兽破坏。那之后，选这张卡或者自己场上1只「弹丸」怪兽破坏。 ②：这张卡在墓地存在的场合，以自己墓地1只「枪管」怪兽或者「弹丸」怪兽为对象才能发动。选自己的手卡·场上1张卡破坏，作为对象的怪兽加入手卡。'),
(27548199, 'Borreload Savage Dragon', '枪管上膛狞猛龙', 'ヴァレルロード・S・ドラゴン', 'Synchro Monster', 'Dragon', 'DARK', 8, 3000, 2500, '调整＋调整以外的怪兽1只以上 这个卡名的③的效果1回合只能使用1次。 ①：这张卡同调召唤成功的场合才能发动。从自己墓地选1只连接怪兽当作装备卡使用给这张卡装备，那个连接标记数量的枪管指示物给这张卡放置。 ②：这张卡的攻击力上升这张卡的效果装备的怪兽的攻击力一半数值。 ③：对方的效果发动时，把这张卡1个枪管指示物取除才能发动。那个发动无效。'),
(66452432, 'Borrelshroud Dragon', '枪管战幕龙', 'ヴァレルシュラウド・ドラゴン', 'Link Monster', 'Dragon', 'DARK', NULL, 3500, NULL, '效果怪兽3只以上 ①：对方不能把场上的这张卡解放。 ②：1回合1次，自己·对方的主要阶段，以自己场上1只「弹丸」怪兽为对象才能发动（对方不能对应这个发动把卡的效果发动）。对方场上1张表侧表示卡的效果无效。那之后，作为对象的怪兽破坏。 ③：只在这张卡表侧表示存在才有1次，自己·对方的战斗阶段开始时才能发动。从额外卡组把1只连接4以下的「枪管」连接怪兽特殊召唤。'),
(85289965, 'Borrelsword Dragon', '枪管刺刀龙', 'ヴァレルソード・ドラゴン', 'Link Monster', 'Dragon', 'DARK', NULL, 3000, NULL, '效果怪兽3只以上 ①：这张卡不会被战斗破坏。 ②：自己·对方回合1次，以1只攻击表示怪兽为对象才能发动（对方不能对应这个效果的发动把卡的效果发动）。那只怪兽变成守备表示。这个回合，这张卡在同1次的战斗阶段中可以作2次攻击。 ③：1回合1次，这张卡向表侧表示怪兽攻击宣言时才能发动。直到回合结束时，这张卡的攻击力上升那只怪兽的攻击力一半数值，那只怪兽的攻击力变成一半。'),
(4909946, 'Boss on Parade', '头目轮战', 'ボスオンパレード', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，从卡组把1只「巨大战舰」怪兽加入手卡。 ②：1回合1次，自己主要阶段才能发动。自己的手卡·场上1只怪兽破坏，从卡组把1只攻击力1200而守备力1000以下的机械族·光属性怪兽在自己或对方的场上特殊召唤。 ③：把墓地的这张卡除外才能发动。从自己的卡组·墓地把1张「头目连战」在自己场上表侧表示放置。'),
(66947414, 'Boss Rush', '头目连战', 'ボスラッシュ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己没有把怪兽通常召唤的回合才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，自己不能把怪兽通常召唤。 ②：这张卡在魔法与陷阱区域存在的状态，自己场上的表侧表示的「巨大战舰」怪兽被破坏送去墓地的场合，那个回合的结束阶段才能发动。从卡组把1只「巨大战舰」怪兽特殊召唤。'),
(45951104, 'Bot Herder', '僵尸牧人', 'ボット・ハーダー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以对方场上1只里侧守备表示怪兽或者原本持有者是自己的表侧表示怪兽为对象才能发动。作为对象的怪兽不存在的场合或者作为对象的怪兽的原本持有者是自己的场合（里侧表示卡翻开确认），以下效果各适用。 ●给与对方200伤害。 ●除作为对象的怪兽外的对方场上的全部怪兽的控制权得到。'),
(84824601, 'Botanical Girl', '植物少女', 'ボタニティ・ガール', 'Effect Monster', 'Plant', 'WATER', 3, 1300, 1100, '这张卡从场上送去墓地时，可以从自己卡组把1只守备力1000以下的植物族怪兽加入手卡。'),
(20546916, 'Botanical Lion', '植物狮子', 'ボタニカル・ライオ', 'Effect Monster', 'Plant', 'EARTH', 4, 1600, 2000, '自己场上表侧表示存在的植物族怪兽每有1只，这张卡的攻击力上升300。这张卡只要在场上表侧表示存在，控制权不能变更。'),
(81386177, 'Bottom Dweller', '神鱼', '神魚', 'Normal Monster', 'Fish', 'WATER', 5, 1650, 1700, '在水中幽雅游动的鱼神，若它发怒会很危险。'),
(76532077, 'Bottomless Shifting Sand', '无底的流沙', '底なし流砂', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方的回合结束时，全场的最高攻击力的表侧表示的怪兽破坏。自己的准备阶段时，自己的手卡4张以下的场合，这张卡破坏。'),
(29401950, 'Bottomless Trap Hole', '奈落的落穴', '奈落の落とし穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方把攻击力1500以上的怪兽召唤·反转召唤·特殊召唤时才能发动。那些攻击力1500以上的怪兽破坏并除外。'),
(9540040, 'Boulder Tortoise', '岩石龟', '岩石カメッター', 'Normal Monster', 'Aqua', 'WATER', 6, 1450, 2200, '全身由岩石做成的龟。特点是守备力非常高。'),
(53610653, 'Bound Wand', '咒缚魔杖', 'バウンド・ワンド', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '魔法师族怪兽才能装备。 ①：装备怪兽的攻击力上升装备怪兽的等级×100。 ②：装备怪兽被对方破坏，这张卡被送去墓地的场合才能发动。那只怪兽从墓地往自己场上特殊召唤。'),
(32296881, 'Bountiful Artemis', '丰穰之阿耳特弥斯', '豊穣のアルテミス', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1600, 1700, '①：只要这张卡在怪兽区域存在，每次自己或者对方把反击陷阱卡发动，自己从卡组抽1张。'),
(48582558, 'Bounzer Guard', '保镖防御', 'バウンサー・ガード', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上1只名字带有「保镖」的怪兽才能发动。这个回合，选择的怪兽不会成为卡的效果的对象，不会被战斗破坏。这个回合，对方怪兽攻击的场合，必须把选择的怪兽作为攻击对象。'),
(52090844, 'Bowganian', '弩弓手', 'ボーガニアン', 'Effect Monster', 'Machine', 'DARK', 3, 1300, 1000, '①：自己准备阶段发动。给与对方600伤害。'),
(55351724, 'Bownty', '犬赏金', '犬賞金', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己怪兽的攻击破坏对方怪兽时，以自己墓地1张卡为对象才能发动。那张卡加入手卡。这个回合，自己不能作这个效果加入手卡的卡以及那些同名卡的效果的发动。'),
(81587028, 'Box of Friends', '玩具盒', 'おもちゃ箱', 'Effect Monster', 'Machine', 'LIGHT', 1, NULL, NULL, '这个卡名的效果1回合只能使用1次。 ①：这张卡被破坏送去墓地的场合才能发动。从卡组把2只攻击力或守备力是0的通常怪兽守备表示特殊召唤（同名卡最多1张）。这个效果特殊召唤的怪兽不能作为同调素材，下次的自己结束阶段破坏。'),
(61156777, 'BOXer', '纸箱拳击手', 'BOXサー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 1000, '①：这张卡战斗破坏对方怪兽送去墓地时才能发动。给这张卡放置1个指示物。 ②：把有指示物2个以上放置的这张卡送去墓地才能发动。从卡组把1只地属性怪兽特殊召唤。 ③：这张卡被战斗·效果破坏的场合，可以作为代替把这张卡1个指示物取除。'),
(45025640, 'Boycotton', '拒绝棉羊', 'ボイコットン', 'Effect Monster', 'Plant', 'EARTH', 4, 1000, 2500, '①：这张卡的战斗发生的对对方的战斗伤害由自己代受。 ②：这张卡的战斗不让这张卡被破坏，让自己受到战斗伤害的场合发动。这张卡回到持有者手卡。'),
(16507828, 'Bracchio-raidus', '腕龙雷德斯', 'ブラキオレイドス', 'Fusion Monster', 'Dinosaur', 'WATER', 6, 2200, 2000, '「双头恐龙王」＋「贪尸龙」'),
(87910978, 'Brain Control', '洗脑', '洗脳－ブレインコントロール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：支付800基本分，以对方场上1只可以通常召唤的表侧表示怪兽为对象才能发动。那只表侧表示怪兽的控制权直到结束阶段得到。'),
(44265115, 'Brain Controller', '大脑控制者', 'ブレインコントローラー', 'Tuner Monster', 'Psychic', 'DARK', 1, 100, 200, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「洗脑」加入手卡。 ②：自己把基本分支付的场合，以场上1只表侧表示怪兽为对象，宣言1～8的任意等级才能发动。那只怪兽的等级变成宣言的等级。 ③：这张卡作为同调素材送去墓地的场合才能发动。这张卡效果无效在对方场上守备表示特殊召唤。'),
(81919143, 'Brain Crusher', '大脑破坏虫', 'ブレイン・クラッシャー', 'Effect Monster', 'Insect', 'DARK', 7, 2400, 1500, '这张卡战斗破坏对方怪兽送去墓地的场合，可以使破坏的1只怪兽在那个回合的结束阶段时从墓地特殊召唤到自己场上。这个效果1回合只能使用1次。'),
(17313545, 'Brain Golem', '巨脑怪', 'ゴーレム', 'Effect Monster', 'Fiend', 'DARK', 6, 2500, 1800, '只要这张卡在场上表侧表示存在，场上表侧表示存在的光属性怪兽的效果无效化。这张卡战斗破坏光属性怪兽的场合，只有1次可以继续攻击。'),
(39531794, 'Brain Hazard', '脑灾害', 'ブレインハザード', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：以除外的1只自己的念动力族怪兽为对象才能把这张卡发动。那只怪兽特殊召唤。这张卡从场上离开时那只怪兽破坏。那只怪兽破坏时这张卡破坏。'),
(40267580, 'Brain Jacker', '捕脑魔', 'ブレイン・ジャッカー', 'Flip Effect Monster', 'Fiend', 'DARK', 2, 200, 900, '反转：这张卡当作装备卡使用，装备到对方场上的怪兽上。获得这张卡装备的怪兽的控制权。每次对方准备阶段对方基本分回复500。'),
(85668449, 'Brain Research Lab', '脑开发研究所', '脳開発研究所', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，双方玩家在通常召唤外加上只有1次，自身的主要阶段可以把1只念动力族怪兽召唤。每次这个方法让念动力族怪兽召唤给这张卡放置1个念力指示物。 ②：自己场上的念动力族怪兽为让效果发动而支付基本分的场合，可以作为代替给这张卡放置1个念力指示物。 ③：这张卡从场上离开时自己受到这张卡放置的念力指示物数量×1000伤害。'),
(59258334, 'Brainwashing Beam', '洗脑光线', '洗脳光線', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '选择放置有A指示物的对方场上1只怪兽得到控制权。每次自己的结束阶段时，得到控制权的怪兽的A指示物取除1个。得到控制权的怪兽的A指示物全部被取除或者那只怪兽被破坏的场合，这张卡破坏。'),
(6560411, 'Bramble Rose Dragon', '黑破灭蔷薇龙', '黒薔薇の破滅竜', 'Synchro Monster', 'Plant', 'FIRE', 7, 2400, 1800, '植物族调整＋调整以外的怪兽1只以上 这个卡名的②③的效果1回合各能使用1次。 ①：每次对方把怪兽的效果发动，给与对方600伤害，对方场上的全部怪兽的攻击力下降600。 ②：自己·对方的主要阶段，把这张卡解放才能发动。从额外卡组把1只「黑蔷薇龙」当作同调召唤作特殊召唤。 ③：把墓地的这张卡除外才能发动。从自己墓地把1只4星以下的植物族调整特殊召唤。'),
(30548775, 'Branch!', '分体', 'ブランチ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '融合怪兽在场上被破坏送去墓地时，可以把自己墓地存在的那只融合怪兽进行融合时所使用过的1只融合素材怪兽特殊召唤。'),
(6763530, 'Branded Banishment', '烙印放逐', '烙印追放', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只「死狱乡」怪兽或者8星以上的融合怪兽为对象才能发动。那只怪兽特殊召唤。那之后，以下效果可以适用。 ●自己·对方场上的怪兽作为融合素材除外，把1只8星以上的融合怪兽融合召唤。'),
(32756828, 'Branded Beast', '烙印之兽', '烙印の獣', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，自己·对方的主要阶段，自己场上有「深渊之兽」怪兽存在的场合，把自己场上1只龙族怪兽解放，以对方场上1张卡为对象才能发动。那张卡破坏。 ②：自己·对方的结束阶段，以自己墓地1张「烙印」永续魔法·永续陷阱卡为对象才能发动。那张卡在自己场上表侧表示放置。'),
(60442460, 'Branded Befallen', '被引导的烙印', '導かれし烙印', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，只以自己场上的「深渊之兽」怪兽1只为对象的卡的效果由对方发动时或者对方连锁自己的「深渊之兽」怪兽的效果的发动把卡的效果发动时，以自己或者对方的墓地1只光·暗属性怪兽为对象才能发动。那只怪兽除外，那个发动的效果无效。'),
(62022479, 'Branded Bond', '烙印之绊', '烙印の絆', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的手卡·墓地·除外状态的1只「阿不思的落胤」特殊召唤。 ②：这张卡为让「阿不思的落胤」的效果发动而被送去墓地的回合的结束阶段才能发动。这张卡在自己场上盖放。'),
(34536828, 'Branded Disciple', '烙印之使徒', '烙印の使徒', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方发动的怪兽的效果处理时，自己场上有8星以上的恶魔族融合怪兽存在，那只对方怪兽的攻击力或者守备力是0的场合，可以把那个发动的效果无效。 ②：攻击力0的怪兽之间进行战斗的伤害步骤结束时才能发动。那只进行战斗的对方怪兽破坏。'),
(1041278, 'Branded Expulsion', '分离烙印', '分かつ烙印', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只融合怪兽解放，以自己或对方的墓地·除外状态的除融合怪兽外的2只怪兽为对象才能发动。那些怪兽在双方场上各1只特殊召唤。把需以「阿不思的落胤」为融合素材的融合怪兽解放来把这张卡发动的场合，可以作为代替把作为对象的2只怪兽在自己场上守备表示特殊召唤。'),
(44362883, 'Branded Fusion', '烙印融合', '烙印融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不是融合怪兽不能从额外卡组特殊召唤。 ①：自己的手卡·卡组·场上的怪兽2只作为融合素材，把以「阿不思的落胤」为融合素材的1只融合怪兽融合召唤。'),
(14220547, 'Branded in Central Dogmatika', '烙印之教导法则', '烙印の命数', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己用魔法卡的效果只把仪式怪兽1只特殊召唤的场合才能发动。把自己或者对方的额外卡组确认，那之内的1只怪兽送去墓地。 ②：自己用魔法卡的效果只把融合怪兽1只特殊召唤的场合，以那1只怪兽为对象才能发动。那只怪兽直到回合结束时攻击力上升自身的原本攻击力数值，只能向对方场上的攻击表示怪兽攻击。'),
(29948294, 'Branded in High Spirits', '烙印之气炎', '烙印の気炎', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把手卡1只怪兽给对方观看，和那只怪兽相同种族而攻击力或守备力是2500的1只8星融合怪兽从额外卡组送去墓地。那之后，以下效果可以适用。 ●给人观看的怪兽丢弃，把1只「阿不思的落胤」或者有那个卡名记述的怪兽从卡组加入手卡。 ②：这个回合有融合怪兽被送去自己墓地的场合，结束阶段才能发动。墓地的这张卡加入手卡。'),
(82738008, 'Branded in Red', '赫之烙印', '赫の烙印', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只「死狱乡」怪兽或「阿不思的落胤」为对象才能发动。那只怪兽加入手卡。那之后，以下效果可以适用。 ●自己的手卡·场上的怪兽作为融合素材除外，把1只8星以上的融合怪兽融合召唤。这个效果特殊召唤的怪兽在这个回合不能直接攻击。'),
(34995106, 'Branded in White', '白之烙印', '白の烙印', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：包含龙族怪兽的自己的手卡·场上的怪兽作为融合素材，把1只融合怪兽融合召唤。把自己的「阿不思的落胤」作为融合素材的场合，也能把自己墓地的怪兽除外作为融合素材。 ②：这张卡为让「阿不思的落胤」的效果发动而被送去墓地的回合的结束阶段才能发动。这张卡在自己场上盖放。'),
(10065487, 'Branded Loss', '烙印丧失', '烙印喪失', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只融合怪兽和从额外卡组特殊召唤的对方场上1只怪兽为对象才能发动。那些怪兽回到持有者卡组。这个回合的结束阶段，双方各自可以从自身的额外卡组把以「阿不思的落胤」为融合素材的1只融合怪兽特殊召唤。'),
(18973184, 'Branded Lost', '失烙印', '失烙印', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，包含把融合怪兽融合召唤效果的效果由自己发动的场合，那个发动不会被无效化，在那次融合召唤成功时对方不能把魔法·陷阱·怪兽的效果发动。 ②：自己把融合怪兽融合召唤的场合才能发动。把1只「阿不思的落胤」或者有那个卡名记述的怪兽从卡组加入手卡。'),
(36637374, 'Branded Opening', '烙印开幕', '烙印開幕', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：选自己1张手卡丢弃。那之后，从卡组选1只「死狱乡」怪兽加入手卡或守备表示特殊召唤。这张卡的发动后，直到回合结束时自己不是融合怪兽不能从额外卡组特殊召唤。 ②：自己场上的融合怪兽被效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(34090915, 'Branded Regained', '复烙印', '復烙印', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次，②的效果在同一连锁上只能发动1次。 ①：光·暗属性怪兽被表侧除外的场合，以那之内的1只为对象才能发动。那只怪兽回到卡组最下面，自己抽1张。 ②：1回合1次，对方把怪兽召唤·特殊召唤的场合，以自己墓地1只「深渊之兽」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(17751597, 'Branded Retribution', '烙印断罪', '烙印断罪', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：包含把怪兽特殊召唤效果的怪兽的效果·魔法·陷阱卡发动时才能发动。需以「阿不思的落胤」为融合素材的融合怪兽从自己场上的表侧表示怪兽之中选1只或者从自己墓地选2只回到额外卡组，那个发动无效并破坏。 ②：把墓地的这张卡除外，以「烙印断罪」以外的自己墓地1张「烙印」魔法·陷阱卡为对象才能发动。那张卡加入手卡。'),
(81767888, 'Branded Sword', '烙印之剑', '烙印の剣', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从自己墓地把「烙印」魔法·陷阱卡任意数量除外才能发动。除外数量的「冰剑衍生物」（龙族·暗·8星·攻2500/守2000）在自己场上特殊召唤。 ②：把墓地的这张卡除外，以自己的除外状态的1只「阿不思的落胤」或者有那个卡名记述的怪兽为对象才能发动。那只怪兽加入手卡。'),
(74277583, 'Brave Scizzar', '剪刀勇士', 'ブレイブ・シザー', 'Normal Monster', 'Machine', 'DARK', 4, 1300, 1000, '熟练地利用几个夹子切向对方。'),
(88305705, 'Brave-Eyes Pendulum Dragon', '勇气眼灵摆龙', 'ブレイブアイズ・ペンデュラム・ドラゴン', 'Fusion Monster', 'Dragon', 'DARK', 8, 3000, 2000, '「灵摆龙」怪兽＋战士族怪兽 ①：这张卡融合召唤成功时才能发动。对方场上的全部怪兽的攻击力变成0。这个回合，这张卡以外的自己怪兽不能攻击。 ②：只要这张卡在怪兽区域存在，攻击力0的怪兽发动的效果无效化。 ③：这张卡的攻击没让对方怪兽被破坏的伤害步骤结束时才能发动。那只对方怪兽除外。'),
(78161361, 'Bravedrive', '驱动勇士', 'ドライブレイブ', 'Effect Monster', 'Cyberse', 'FIRE', 4, 1500, 1000, '①：1回合1次，自己的电子界族怪兽的攻击宣言时，从手卡丢弃1只怪兽才能发动。那只攻击怪兽的攻击力直到回合结束时上升600。'),
(66740005, 'Bravo, Fighter Fur Hire', '空牙团的斗士 布拉沃', '空牙団の闘士 ブラーヴォ', 'Effect Monster', 'Reptile', 'FIRE', 4, 1900, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡把「空牙团的斗士 布拉沃」以外的1只「空牙团」怪兽特殊召唤。 ②：这张卡已在怪兽区域存在的状态，自己场上有这张卡以外的「空牙团」怪兽特殊召唤的场合才能发动。场上的全部「空牙团」怪兽的攻击力·守备力直到回合结束时上升500。'),
(9852718, 'Break Away', '诀别', '決別', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方战斗阶段从手卡把1张魔法卡送去墓地才能发动。那次战斗阶段结束。场上的表侧表示怪兽直到回合结束时效果无效化。'),
(56526564, 'Break Off Trap Hole', '绝缘的落穴', '絶縁の落とし穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：连接怪兽连接召唤成功时才能发动。场上的不在连接状态的怪兽全部破坏。'),
(4008212, 'Break the Destiny', '打破命运', 'ブレイク・ザ・デステニー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1只「龙骑士 D-终」或者8星以上的「命运英雄」怪兽为对象才能发动。那只怪兽破坏，下次的对方主要阶段1跳过。 ②：把墓地的这张卡除外才能发动。把「打破命运」以外的有「龙骑士 D-终」的卡名或者「命运英雄」怪兽的卡名记述的1张魔法·陷阱卡从卡组加入手卡。'),
(69873498, 'Break the Seal', '破除封印', 'ブレイク・ザ・シール', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：可以从以下效果选择1个发动。 ●从自己的卡组·墓地把1张「破除封印」在自己场上表侧表示放置。 ●把包含这张卡的自己场上2张表侧表示的「破除封印」送去墓地才能发动。从卡组把1只「被封印」怪兽加入手卡。 ②：场上的这张卡被破坏的场合，把手卡最多5只「被封印」怪兽给对方观看才能发动。那个数量的对方场上的卡回到手卡。'),
(63851864, 'Break! Draw!', '破坏抽卡', 'ブレイク・ドロー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '机械族怪兽才能装备。装备怪兽战斗破坏对方怪兽送去墓地时，从自己卡组抽1张卡。这张卡在发动后第3次的自己的结束阶段时破坏。'),
(22923081, 'Breaker the Dark Magical Warrior', '黑之魔导战士 破坏者', '黒魔導戦士 ブレイカー', 'Effect Monster', 'Spellcaster', 'DARK', 6, 1600, 1000, '「黑魔导战士 破坏者」的④的效果1回合只能使用1次。 ①：这张卡召唤成功的场合发动。给这张卡放置2个魔力指示物。 ②：这张卡灵摆召唤成功的场合发动。给这张卡放置3个魔力指示物。 ③：这张卡的攻击力上升这张卡的魔力指示物数量×400。 ④：把这张卡1个魔力指示物取除，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(71413901, 'Breaker the Magical Warrior', '魔导战士 破坏者', '魔導戦士 ブレイカー', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1600, 1000, '①：这张卡召唤的场合发动。给这张卡放置1个魔力指示物（最多1个）。 ②：这张卡的攻击力上升这张卡的魔力指示物数量×300。 ③：把这张卡1个魔力指示物取除，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(69217334, 'Breaking of the World', '世界粉碎', 'ブレイク・オブ・ザ・ワールド', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：1回合1次，以自己场上1只仪式怪兽为对象才能发动。手卡1只仪式怪兽直到回合结束时公开。那只公开的仪式怪兽的等级直到回合结束时变成和作为对象的怪兽的等级相同。 ②：1回合1次，自己场上有「破灭之女神 露茵」或者「终焉之王 迪米斯」仪式召唤的场合，可以从以下效果选择1个发动。 ●自己从卡组抽1张。 ●选场上1张卡破坏。'),
(78474168, 'Breakthrough Skill', '突破技能', 'ブレイクスルー・スキル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以对方场上1只效果怪兽为对象才能发动。那只对方怪兽的效果直到回合结束时无效。 ②：自己回合把墓地的这张卡除外，以对方场上1只效果怪兽为对象才能发动。那只对方的效果怪兽的效果直到回合结束时无效。这个效果在这张卡送去墓地的回合不能发动。'),
(96218085, 'Breakthrough!', '中央突破', '中央突破', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只名字带有「六武众」的怪兽发动。这个回合的战斗阶段中，选择怪兽战斗破坏对方怪兽的场合，自己场上存在的「大将军 紫炎」或者名字带有「六武众」的怪兽可以直接攻击对方玩家。'),
(44221928, 'Breath of Acclamation', '褒誉之息吹', '褒誉の息吹', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '风属性仪式怪兽的降临必需。 ①：等级合计直到变成和仪式召唤的怪兽相同为止，把自己的手卡·场上的怪兽解放，从手卡把1只风属性仪式怪兽仪式召唤。'),
(20101223, 'Breath of Light', '神之息吹', '神の息吹', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '场上表侧表示存在的岩石族怪兽全部破坏。'),
(64018647, 'Breath of Resurrection', '回生气息', 'リザレクション・ブレス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「勇者衍生物」存在的场合才能发动。从自己的手卡·墓地选最多2只怪兽特殊召唤（同名卡最多1张）。那之后，可以从自己的手卡·墓地选有「勇者衍生物」的衍生物名记述的1张装备魔法卡给自己场上1只可以装备的怪兽装备。这个效果特殊召唤的怪兽从场上离开的场合除外。'),
(58882608, 'Breath of the Tistina', '提斯蒂娜的气息', 'ティスティナの息吹', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己在通常召唤外加上只有1次，自己主要阶段可以把1只「提斯蒂娜」怪兽召唤。 ②：以自己场上1只表侧表示怪兽为对象才能发动（自己场上有光属性「提斯蒂娜」怪兽存在的场合，也能作为代替以对方场上1只表侧表示怪兽为对象）。那只怪兽变成里侧守备表示。那之后，「提斯蒂娜的息吹」以外的1张「提斯蒂娜」卡从卡组加入手卡。'),
(90011273, 'Breechborrel Dragon', NULL, NULL, 'Link Monster', 'Dragon', 'DARK', NULL, 1200, NULL, NULL),
(52840598, 'Bri Synchron', '无赖同调士', 'ブライ・シンクロン', 'Tuner Monster', 'Machine', 'EARTH', 4, 1500, 1100, '这张卡作为同调召唤的素材送去墓地的场合，直到这个回合的结束阶段时，这张卡为同调素材的同调怪兽攻击力上升600，效果无效化。'),
(24707869, 'Bright Future', '光明的未来', 'ブライト・フューチャー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择从游戏中除外的2只自己的念动力族怪兽发动。选择的怪兽回到墓地，从自己卡组抽1张卡。'),
(16719802, 'Bright Star Dragon', '星辉龙', 'スター・ブライト・ドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 4, 1900, 1000, '这张卡召唤成功时，可以选择这张卡以外的场上表侧表示存在的1只怪兽，直到结束阶段时等级上升2星。'),
(19271881, 'Brightest, Blazing, Branded King', '赫耀的王之烙印', '赫ける王の烙印', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：选需以「阿不思的落胤」为融合素材的自己场上1只融合怪兽，那只怪兽以外的场上的全部表侧表示的卡的效果直到回合结束时无效。 ②：这个回合有融合怪兽被送去自己墓地的场合，结束阶段才能发动。墓地的这张卡加入手卡。'),
(34848821, 'Brigrand the Glory Dragon', '痕喰龙 蛮寇兽种', '痕喰竜ブリガンド', 'Fusion Monster', 'Beast', 'DARK', 8, 2500, 2000, '「阿不思的落胤」＋8星以上的怪兽 这个卡名的③的效果1回合只能使用1次。 ①：这张卡不会被战斗破坏。 ②：只要融合召唤的这张卡在怪兽区域存在，对方不能把自己场上的其他怪兽作为怪兽的效果的对象。 ③：这张卡被送去墓地的回合的结束阶段才能发动。从卡组选1只「铁兽」怪兽或「阿不思的落胤」加入手卡或特殊召唤。'),
(7394770, 'Brilliant Fusion', '璀璨结合', 'ブリリアント・フュージョン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，自己卡组的怪兽作为融合素材，把1只「宝石骑士」融合怪兽攻击力·守备力变成0融合召唤。这张卡从场上离开时那只怪兽破坏。 ②：1回合1次，从手卡丢弃1张魔法卡才能发动。这张卡的①的效果特殊召唤的怪兽的攻击力·守备力直到对方回合结束时上升原本数值。'),
(61011438, 'Brilliant Rose', '璀璨蔷薇', 'ブリリアント・ローズ', 'Effect Monster', 'Rock', 'LIGHT', 2, 500, 500, '这个卡名在规则上也当作「宝石骑士」卡使用。这个卡名的①的效果1回合只能使用1次。 ①：从手卡丢弃1张其他的「宝石骑士」卡或「幻奏」卡才能发动。这张卡从手卡特殊召唤。 ②：1回合1次，从额外卡组把1只「宝石骑士」怪兽或「幻奏」怪兽送去墓地才能发动。这张卡的卡名·种族·属性直到结束阶段变成和为这个效果发动而送去墓地的怪兽的原本的卡名·种族·属性相同。'),
(3105404, 'Brilliant Spark', '明亮火花', 'ブリリアント・スパーク', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「明亮火花」在1回合只能发动1张。 ①：自己场上的「宝石骑士」怪兽被对方怪兽的攻击或者对方的效果破坏的场合，以破坏的那1只怪兽为对象才能发动。给与对方那只怪兽的原本攻击力数值的伤害。 ②：这张卡在墓地存在的场合，把手卡1张「宝石骑士」卡送去墓地才能发动。这张卡加入手卡。'),
(2102065, 'Brinegir', '死亡冰柱水马', 'ブライニグル', 'Effect Monster', 'Sea Serpent', 'WATER', 7, 1000, 2600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，以自己墓地1只水属性怪兽为对象才能发动。这张卡的攻击力直到回合结束时上升作为对象的怪兽的攻击力数值。 ②：这张卡被送去墓地的场合，以自己场上1只水属性怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升1000。'),
(50321796, 'Brionac, Dragon of the Ice Barrier', '冰结界之龙 光枪龙', '氷結界の龍 ブリューナク', 'Synchro Monster', 'Sea Serpent', 'WATER', 6, 2300, 1400, '调整＋调整以外的怪兽1只以上 这个卡名的效果1回合只能使用1次。 ①：把手卡任意数量丢弃去墓地，以丢弃数量的对方场上的卡为对象才能发动。那些卡回到手卡。'),
(65892310, 'Brionac, the Magical Ice Dragon', '冰魔龙 光枪龙', '氷魔龍 ブリューナク', 'Synchro Monster', 'Sea Serpent', 'WATER', 6, 2300, 1400, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合，丢弃1张手卡，以场上1张卡为对象才能发动。那张卡回到手卡。 ②：这张卡从墓地特殊召唤的场合，丢弃1张手卡，以场上1张卡为对象才能发动。那张卡回到手卡。'),
(27217742, 'Brohunder', '雷电哥哥', 'ONiサンダー', 'Effect Monster', 'Thunder', 'LIGHT', 4, 900, 400, '①：这张卡召唤成功时才能发动。从卡组把「雷电哥哥」以外的1只雷族·光属性·4星怪兽加入手卡。'),
(41587307, 'Broken Bamboo Sword', '折断的竹光', '折れ竹光', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：装备怪兽的攻击力上升0。'),
(60930169, 'Broken Blocker', '断裂的防壁', 'ブロークン・ブロッカー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的守备力比攻击力高的守备表示怪兽被战斗破坏的场合才能发动。和那只怪兽同名怪兽最多2只从自己卡组表侧守备表示特殊召唤。'),
(88086137, 'Broken Line', '直通断线', '直通断線', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：和这张卡相同纵列有怪兽的效果·魔法·陷阱卡发动时才能把盖放的这张卡发动。那个发动无效并破坏。'),
(57985393, 'Broomy', '布噜咪', 'ブルーミー', 'Tuner Monster', 'Spellcaster', 'LIGHT', 2, 700, 700, '这个卡名的效果1回合只能使用1次，把这张卡作为同调素材的场合，不是8星以下的怪兽的同调召唤不能使用。 ①：把手卡的这张卡和手卡1只怪兽给对方观看才能发动。那2只之内的1只特殊召唤，另1只除外。这个效果的发动后，直到回合结束时自己不是同调怪兽不能从额外卡组特殊召唤，不用同调怪兽不能攻击宣言。'),
(6353603, 'Brotherhood of the Fire Fist - Bear', '暗炎星－熊志', '暗炎星－ユウシ', 'Effect Monster', 'Beast-Warrior', 'FIRE', 4, 1600, 1200, '1回合1次，这张卡给与对方基本分战斗伤害时，可以从卡组选1张名字带有「炎舞」的魔法卡在自己场上盖放。此外，1回合1次，把自己场上表侧表示存在的1张名字带有「炎舞」的魔法·陷阱卡送去墓地才能发动。选择场上1只怪兽破坏。'),
(66762372, 'Brotherhood of the Fire Fist - Boar', '孤炎星－鲁猪深', '孤炎星－ロシシン', 'Tuner Monster', 'Beast-Warrior', 'FIRE', 4, 1100, 1400, '把这张卡作为同调素材的场合，不是炎属性怪兽的同调召唤不能使用。这张卡被战斗破坏送去墓地时，可以从卡组把「孤炎星-鲁猪深」以外的1只名字带有「炎星」的4星怪兽特殊召唤。1回合1次，这张卡在场上存在的场合名字带有「炎星」的怪兽从自己的额外卡组特殊召唤时，可以从卡组选1张名字带有「炎舞」的魔法卡在自己场上盖放。'),
(92572371, 'Brotherhood of the Fire Fist - Buffalo', '杀炎星－牛逵', '殺炎星－ブルキ', 'Effect Monster', 'Beast-Warrior', 'FIRE', 4, 1700, 1000, '这张卡在墓地存在的场合，把手卡或者自己场上表侧表示存在的名字带有「炎星」或者「炎舞」的卡合计2张送去墓地才能发动。这张卡从墓地特殊召唤。「杀炎星-牛逵」的效果1回合只能使用1次。'),
(58504745, 'Brotherhood of the Fire Fist - Cardinal', '间炎星－红冠胜', '間炎星－コウカンショウ', 'XYZ Monster', 'Beast-Warrior', 'FIRE', 4, 1800, 2200, '名字带有「炎星」的4星怪兽×2 把这张卡2个超量素材取除才能发动。选择自己的场上·墓地的名字带有「炎星」或者「炎舞」的卡合计2张和对方墓地或者对方场上表侧表示存在的卡合计2张回到持有者卡组。「闲炎星-红冠胜」的效果1回合只能使用1次。'),
(93751476, 'Brotherhood of the Fire Fist - Caribou', '猛炎星－驯鹿明', '猛炎星－テンレイ', 'Effect Monster', 'Beast-Warrior', 'FIRE', 4, 1100, 2000, '这张卡被卡的效果破坏送去墓地的回合的结束阶段时，可以从卡组把「猛炎星-鹿明」以外的1只名字带有「炎星」的4星怪兽特殊召唤。这张卡被名字带有「炎星」的同调怪兽的同调召唤使用送去墓地的场合，可以从卡组选1张名字带有「炎舞」的魔法卡在自己场上盖放。'),
(49785720, 'Brotherhood of the Fire Fist - Coyote', '机炎星－郊狼用', '機炎星－ゴヨウテ', 'Effect Monster', 'Beast-Warrior', 'FIRE', 5, 2000, 500, '自己场上有名字带有「炎舞」的魔法·陷阱卡存在，自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。'),
(43748308, 'Brotherhood of the Fire Fist - Dragon', '微炎星－龙进', '微炎星－リュウシシン', 'Effect Monster', 'Beast-Warrior', 'FIRE', 4, 1800, 400, '1回合1次，自己把名字带有「炎舞」的魔法·陷阱卡发动的场合，可以从卡组选1张名字带有「炎舞」的陷阱卡在自己场上盖放。此外，1回合1次，把自己场上表侧表示存在的2张名字带有「炎舞」的魔法·陷阱卡送去墓地才能发动。从自己墓地选择「微炎星-龙史进」以外的1只名字带有「炎星」的怪兽特殊召唤。'),
(46241344, 'Brotherhood of the Fire Fist - Eagle', '炎星仙－鹫真人', '炎星仙－ワシンジン', 'Link Monster', 'Beast-Warrior', 'FIRE', NULL, 1700, NULL, '兽战士族怪兽2只 自己对「炎星仙-鹫真人」1回合只能有1次特殊召唤，那个②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己把「炎星」怪兽的效果发动的场合，也能不把自己的手卡·场上的「炎星」卡以及「炎舞」卡送去墓地来发动。 ②：以自己的场上·墓地1张「炎舞」魔法·陷阱卡为对象才能发动。那张卡回到持有者手卡。那之后，从卡组把1只「炎星」怪兽送去墓地。'),
(61472381, 'Brotherhood of the Fire Fist - Eland', '巧炎星－驼鹿青', '巧炎星－エランセイ', 'Ritual Effect Monster', 'Beast-Warrior', 'FIRE', 6, 2400, 2000, '「炎舞-「洞明」」降临。这个卡名的①②的效果1回合各能使用1次。 ①：从手卡丢弃1只怪兽才能发动。从自己的卡组·墓地选1张「炎舞」魔法·陷阱卡在自己场上盖放。 ②：对方把怪兽的效果发动时，把「巧炎星-巨羚青」以外的自己场上的表侧表示的1张「炎星」卡或者「炎舞」卡送去墓地才能发动。那个效果无效。'),
(98093548, 'Brotherhood of the Fire Fist - Elephant', '俊炎星－象清', '俊炎星－ゾウセイ', 'Effect Monster', 'Beast-Warrior', 'FIRE', 4, 1000, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，把自己场上1张表侧表示的「炎舞」魔法·陷阱卡送去墓地才能发动。从手卡把「俊炎星-象清」以外的1只「炎星」怪兽特殊召唤。 ②：以自己墓地1张「炎舞」魔法·陷阱卡为对象才能发动。那张卡回到卡组。那之后，可以从卡组把1只5星以上的「炎星」怪兽加入手卡。'),
(70355994, 'Brotherhood of the Fire Fist - Gorilla', '勇炎星－猿胜', '勇炎星－エンショウ', 'Effect Monster', 'Beast-Warrior', 'FIRE', 4, 1600, 1000, '1回合1次，这张卡战斗破坏对方怪兽送去墓地时，可以从卡组选1张名字带有「炎舞」的魔法卡在自己场上盖放。此外，1回合1次，把自己场上表侧表示存在的1张名字带有「炎舞」的魔法·陷阱卡送去墓地才能发动。选择场上1张魔法·陷阱卡破坏。'),
(17475251, 'Brotherhood of the Fire Fist - Hawk', '英炎星－鹰荣', '英炎星－ホークエイ', 'Effect Monster', 'Beast-Warrior', 'FIRE', 3, 200, 1500, '这张卡被对方破坏的场合，可以从卡组选1张名字带有「炎舞」的魔法卡在自己场上盖放。此外，自己场上有名字带有「炎舞」的魔法·陷阱卡存在的场合，自己场上的全部名字带有「炎星」的怪兽的攻击力·守备力上升500。'),
(74168099, 'Brotherhood of the Fire Fist - Horse Prince', '炎星侯－马进', '炎星侯－ホウシン', 'Synchro Monster', 'Beast-Warrior', 'FIRE', 6, 2200, 2200, '炎属性调整＋调整以外的怪兽1只以上 ①：这张卡同调召唤成功时才能发动。从卡组把1只炎属性·3星怪兽特殊召唤。 ②：这张卡同调召唤成功的回合，自己不能把5星以上的怪兽特殊召唤。'),
(89856523, 'Brotherhood of the Fire Fist - Kirin', '罡炎星－麟俊义', '罡炎星－リシュンキ', 'Synchro Monster', 'Beast-Warrior', 'FIRE', 8, 2000, 2800, '炎属性调整＋调整以外的名字带有「炎星」的怪兽1只以上 这张卡同调召唤成功时，可以从卡组选1张名字带有「炎舞」的魔法·陷阱卡在自己场上盖放。只要这张卡在场上表侧表示存在，对方场上的怪兽的攻击力下降自己场上表侧表示存在的魔法·陷阱卡数量×100的数值。'),
(39699564, 'Brotherhood of the Fire Fist - Leopard', '速炎星－戴豹', '速炎星－タイヒョウ', 'Effect Monster', 'Beast-Warrior', 'FIRE', 3, NULL, 200, '这张卡召唤·特殊召唤成功的回合的主要阶段时，把自己场上1只名字带有「炎星」的怪兽解放才能发动。从卡组选1张名字带有「炎舞」的魔法·陷阱卡在自己场上盖放。「速炎星-戴豹」的效果1回合只能使用1次。'),
(37057743, 'Brotherhood of the Fire Fist - Lion Emperor', '炎星皇－晁怒狮', '炎星皇－チョウライオ', 'XYZ Monster', 'Beast-Warrior', 'FIRE', 3, 2200, 200, '炎属性3星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以自己墓地1只炎属性怪兽为对象才能发动。那只炎属性怪兽加入手卡。这个效果的发动后，直到回合结束时自己不能把作为对象的怪兽以及那些同名怪兽召唤·特殊召唤。'),
(35488287, 'Brotherhood of the Fire Fist - Panda', '寿炎星－李熊猫', '寿炎星－リシュンマオ', 'Effect Monster', 'Beast-Warrior', 'FIRE', 5, 2100, 400, '这个卡名的①②的效果1回合各能使用1次。 ①：自己把「炎舞」魔法·陷阱卡发动的场合才能发动。这张卡从手卡特殊召唤。那之后，可以从自己墓地选「寿炎星-李熊猫」以外的1只「炎星」怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是「炎星」怪兽不能特殊召唤。 ②：自己场上的「炎星」怪兽被对方的效果破坏的场合，可以作为代替把自己场上1张表侧表示的「炎舞」魔法·陷阱卡送去墓地。'),
(20265095, 'Brotherhood of the Fire Fist - Peacock', '慧炎星－孔雀三娘', '慧炎星－コサンジャク', 'Link Monster', 'Beast-Warrior', 'FIRE', NULL, 1000, NULL, '「炎星」怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡所连接区有「炎星」怪兽存在，对方不能选择这张卡作为攻击对象。 ②：这张卡的攻击宣言时把自己场上1张表侧表示的「炎舞」魔法·陷阱卡送去墓地，以对方场上1只怪兽为对象才能发动。直到结束阶段，那只对方怪兽在这张卡所连接区放置得到控制权。这个效果得到控制权的怪兽不能攻击宣言。'),
(62694833, 'Brotherhood of the Fire Fist - Ram', '魁炎星－羊武', '魁炎星－シーブ', 'Effect Monster', 'Beast-Warrior', 'FIRE', 3, 800, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤成功时，丢弃1张手卡，以自己场上1张「炎舞」魔法·陷阱卡为对象才能发动。从卡组选和那张卡卡名不同的1张「炎舞」魔法·陷阱卡在自己场上盖放。 ②：这张卡用「炎星」怪兽的效果特殊召唤成功的场合才能发动。从卡组选同名卡不在自己墓地存在的1张「炎舞」魔法·陷阱卡在自己场上盖放。'),
(44860890, 'Brotherhood of the Fire Fist - Raven', '捷炎星－鸦清', '捷炎星－セイヴン', 'Effect Monster', 'Beast-Warrior', 'FIRE', 3, 200, 1800, '这张卡从场上送去墓地的场合，可以从卡组选1张名字带有「炎舞」的魔法卡在自己场上盖放。此外，只要这张卡在场上表侧表示存在，自己场上的名字带有「炎舞」的魔法·陷阱卡不会被对方的卡的效果破坏。'),
(66084673, 'Brotherhood of the Fire Fist - Rhino', '空炎星－犀超', '空炎星－サイチョウ', 'Effect Monster', 'Beast-Warrior', 'FIRE', 4, 1700, 1400, '自己场上的名字带有「炎星」的怪兽进行战斗的伤害计算时只有1次，把自己场上表侧表示存在的1张名字带有「炎舞」的魔法·陷阱卡和手卡1只名字带有「炎星」的怪兽送去墓地才能发动。进行战斗的自己怪兽的攻击力只在那次伤害计算时上升送去墓地的怪兽的原本攻击力数值。'),
(30929786, 'Brotherhood of the Fire Fist - Rooster', '立炎星－董鸡', '立炎星－トウケイ', 'Effect Monster', 'Beast-Warrior', 'FIRE', 3, 1500, 100, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡用「炎星」怪兽的效果特殊召唤成功时才能发动。从卡组把1只「炎星」怪兽加入手卡。 ②：1回合1次，把自己场上1张表侧表示的「炎舞」魔法·陷阱卡送去墓地才能发动。从卡组选1张「炎舞」魔法·陷阱卡在自己场上盖放。'),
(75132317, 'Brotherhood of the Fire Fist - Snake', '雄炎星－蛇冲', '雄炎星－スネイリン', 'Effect Monster', 'Beast-Warrior', 'FIRE', 4, 1800, 600, '1回合1次，名字带有「炎舞」的魔法·陷阱卡被送去自己墓地的场合，可以从卡组选1张名字带有「炎舞」的陷阱卡在自己场上盖放。此外，自己场上没有这张卡以外的怪兽存在的场合，1回合1次，把自己场上表侧表示存在的2张名字带有「炎舞」的魔法·陷阱卡送去墓地才能发动。从卡组抽1张卡。'),
(1662004, 'Brotherhood of the Fire Fist - Spirit', '炎星师－张天', '炎星師－チョウテン', 'Tuner Monster', 'Beast-Warrior', 'FIRE', 3, 500, 200, '这个卡名的效果1回合只能使用1次。把这张卡作为同调素材的场合，不是兽战士族怪兽的同调召唤不能使用。 ①：这张卡召唤成功时，以自己墓地1只守备力200以下的炎属性·3星怪兽为对象才能发动。那只炎属性怪兽守备表示特殊召唤。这个效果特殊召唤成功的回合，兽战士族以外的自己怪兽不能攻击。'),
(2521011, 'Brotherhood of the Fire Fist - Swallow', '威炎星－呼燕灼', '威炎星－ヒエンシャク', 'Effect Monster', 'Beast-Warrior', 'FIRE', 5, 2000, 800, '这张卡可以把自己场上表侧表示存在的3张名字带有「炎舞」的魔法·陷阱卡送去墓地，从手卡特殊召唤。这张卡召唤·特殊召唤成功时，可以从卡组选1张名字带有「炎舞」的陷阱卡在自己场上盖放。「威炎星-飞燕灼」的这个效果1回合只能使用1次。此外，只要这张卡在场上表侧表示存在，自己场上的兽战士族怪兽不会成为对方的卡的效果的对象。'),
(93877990, 'Brotherhood of the Fire Fist - Swan', '富炎星－应天鹅', '富炎星－ハクテンオウ', 'Fusion Monster', 'Beast-Warrior', 'FIRE', 8, 2600, 2200, '兽战士族怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。给与对方为自己场上的「炎舞」魔法·陷阱卡数量×200伤害。 ②：自己·对方的战斗阶段，把自己场上1张表侧表示的「炎舞」魔法·陷阱卡送去墓地，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(96381979, 'Brotherhood of the Fire Fist - Tiger King', '魁炎星王－宋虎', '魁炎星王－ソウコ', 'XYZ Monster', 'Beast-Warrior', 'FIRE', 4, 2200, 1800, '兽战士族4星怪兽×2 ①：这张卡超量召唤成功时才能发动。从卡组把1张「炎舞」魔法·陷阱卡盖放。 ②：1回合1次，把这张卡1个超量素材取除才能发动。兽战士族以外的场上的全部效果怪兽的效果直到对方回合结束时无效化。 ③：这张卡从场上送去墓地时，把自己场上3张表侧表示的「炎舞」魔法·陷阱卡送去墓地才能发动。4星以下而相同攻击力的2只兽战士族怪兽从卡组守备表示特殊召唤。'),
(93294869, 'Brotherhood of the Fire Fist - Wolf', '伤炎星－狼松', '傷炎星－ウルブショウ', 'Effect Monster', 'Beast-Warrior', 'FIRE', 3, NULL, 1900, '这张卡反转的场合，可以从卡组选1张名字带有「炎舞」的陷阱卡在自己场上盖放。用反转召唤反转的场合，可以再从卡组选1张名字带有「炎舞」的魔法卡在自己场上盖放。'),
(79126789, 'Broww, Huntsman of Dark World', '暗黑界之猎人 棕布劳', '暗黒界の狩人 ブラウ', 'Effect Monster', 'Fiend', 'DARK', 3, 1400, 800, '①：这张卡被效果从手卡丢弃去墓地的场合发动。自己从卡组抽1张。被对方的效果丢弃的场合，这个效果抽出的数量变成2张。'),
(6214884, 'Brron, Mad King of Dark World', '暗黑界的狂王 布隆', '暗黒界の狂王 ブロン', 'Effect Monster', 'Fiend', 'DARK', 4, 1800, 400, '①：这张卡给与对方战斗伤害时才能发动。选自己1张手卡丢弃。'),
(36569343, 'Brushfire Knight', '红炎之骑士', '紅炎の騎士', 'Effect Monster', 'Warrior', 'FIRE', 4, 1400, 1200, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡已在怪兽区域存在的状态，这张卡以外的炎属性怪兽被破坏送去自己墓地的场合发动。从卡组把1只炎属性怪兽送去墓地。 ②：这张卡被破坏送去墓地的场合发动。从卡组把1只炎属性怪兽送去墓地。'),
(36809777, 'Brutal Beast Battle', '兽烈之争', '獣烈な争い', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：双方玩家在自身场上有相同种类（仪式·融合·同调·超量·连接）的怪兽2只以上存在的场合，直到那种类的怪兽变成1只为止必须送去墓地。那之后，送去墓地的玩家从卡组抽出自身场上的怪兽种类（仪式·融合·同调·超量·连接）的数量。'),
(30155789, 'Brutal Potion', '施虐性媚药', 'サディスティック・ポーション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '发动后这张卡变成装备卡，给自己场上存在的1只怪兽装备。这张卡的控制者用卡的效果给与对方玩家伤害的场合，直到那个回合的结束阶段时装备怪兽的攻击力上升1000。'),
(63503850, 'Brute Enforcer', '蛮力攻击实施员', 'ブルートエンフォーサー', 'Link Monster', 'Cyberse', 'DARK', NULL, 1600, NULL, '效果怪兽2只 这个卡名的效果1回合只能使用1次。 ①：丢弃1张手卡，以对方场上1张表侧表示的卡为对象才能发动。对方可以把原本种类（怪兽·魔法·陷阱）和那张表侧表示的卡相同的1张卡从手卡丢弃让这个效果无效。没丢弃的场合，作为对象的表侧表示的卡破坏。'),
(79777187, 'Bubble Barrier', '护罩泡泡', 'バリア・バブル', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己场上的全部「娱乐伙伴」怪兽以及「娱乐法师」怪兽1回合各有1次不会被战斗·效果破坏。 ②：只要这张卡在魔法与陷阱区域存在，自己场上的「娱乐伙伴」怪兽以及「娱乐法师」怪兽的战斗发生的对自己的战斗伤害变成0。'),
(53586134, 'Bubble Blaster', '水泡发射器', 'バブル・ショット', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「元素英雄 水泡侠」才能装备。装备怪兽的攻击力上升800。装备怪兽被战斗破坏的场合，这张卡代替破坏，装备怪兽的控制者的战斗伤害为0。'),
(58531587, 'Bubble Bringer', '水泡使者', 'バブル・ブリンガー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，4星以上的怪兽不能直接攻击。自己回合可以通过把场上表侧表示存在的这张卡送去墓地，选择自己墓地2只水属性·3星以下的同名怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(61622107, 'Bubble Crash', '泡沫崩溃', 'バブル・クラッシュ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '手卡·场上的卡合计有6张以上的玩家，直到合计变成5张为止，把卡送去墓地。'),
(80075749, 'Bubble Illusion', '水泡幻像', 'バブルイリュージョン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「元素英雄 水泡侠」在自己场上表侧表示存在时才能发动。这个回合，自己可以从手卡发动1张陷阱卡。'),
(61968753, 'Bubble Shuffle', '水泡搅乱', 'バブル・シャッフル', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「元素英雄 水泡侠」在场上表侧表示存在时才能发动。自己场上表侧攻击表示存在的1只「元素英雄 水泡侠」和对方场上表侧攻击表示存在的1只怪兽变成守备表示。把变成守备表示的1只「元素英雄 水泡侠」作为祭品，从手卡特殊召唤1只名字带有「元素英雄」的怪兽。'),
(6104968, 'Bubonic Vermin', '死亡仓鼠', 'デスハムスター', 'Flip Effect Monster', 'Beast', 'EARTH', 3, 900, 600, '①：这张卡反转的场合才能发动。从卡组把1只「死亡仓鼠」里侧守备表示特殊召唤。'),
(26223582, 'Buerillabaisse de Nouvelles', '马赛鱼汤之布耶贝斯・饿魔新飨', 'ブエリヤベース・ド・ヌーベルズ', 'Ritual Effect Monster', 'Beast-Warrior', 'DARK', 1, 400, 1850, '「食谱」卡降临。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。从自己卡组上面把5张卡翻开。可以从那之中选1张「新式魔厨」卡加入手卡。剩余回到卡组。 ②：场上的这张卡成为攻击·效果的对象时才能发动。这张卡和自己·对方场上1只攻击表示怪兽解放，从手卡·卡组把1只2·3星的「新式魔厨」仪式怪兽特殊召唤。'),
(10971759, 'Bug Emergency', '光虫异变', '光虫異変', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「光虫异变」在1回合只能发动1张。 ①：以自己墓地2只昆虫族·3星怪兽为对象才能发动。那些怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。 ②：从自己墓地把这张卡和1只超量怪兽除外才能发动。自己场上的全部昆虫族·3星怪兽的等级直到回合结束时变成和除外的超量怪兽的阶级相同数值的等级。这个效果的发动后，直到回合结束时自己不是昆虫族怪兽不能特殊召唤。'),
(86643777, 'Bug Matrix', '光虫基盘', '光虫基盤', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '「光虫基盘」的②的效果1回合只能使用1次。 ①：自己场上的昆虫族怪兽的攻击力·守备力上升300。 ②：以自己场上1只昆虫族超量怪兽为对象才能发动。把手卡1只昆虫族怪兽在那只怪兽下面重叠作为超量素材。'),
(47185546, 'Bug Signal', '光虫信号', '光虫信号', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「光虫信号」在1回合只能发动1张。 ①：以自己场上1只昆虫族超量怪兽为对象才能发动。比那只自己怪兽阶级高2阶或者阶级低2阶的1只昆虫族超量怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。'),
(19000848, 'Buio the Dawn''s Light', '夜明之光 布幽', NULL, 'Effect Monster', 'Fiend', 'DARK', 3, 1000, 1500, '自己主要怪兽区域左端和右端的怪兽不会被效果破坏。 「夜明之光 布幽」的以下效果1回合各能使用1次。 这张卡在手卡存在的场合：可以以自己场上1只恶魔族效果怪兽为对象；那个效果无效，这张卡特殊召唤。 这张卡被送去墓地的场合：可以从卡组把1张「天国之乱」加入手卡。'),
(23979249, 'Bujin Arasuda', '武神-荒樔田', '武神－アラスダ', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 4, 1600, 1900, '自己的场上·墓地的名字带有「武神」的怪兽从游戏中除外的场合，这张卡可以从手卡表侧守备表示特殊召唤。此外，这张卡在场上表侧表示存在，名字带有「武神」的卡用抽卡以外的方法从自己卡组加入手卡的场合，那个回合的结束阶段时才能发动1次。从卡组抽1张卡，那之后选1张手卡丢弃。「武神-荒樔田」在自己场上只能有1只表侧表示存在。'),
(70026064, 'Bujin Hiruko', '武神-蛭子', '武神－ヒルコ', 'Pendulum Normal Monster', 'Beast-Warrior', 'LIGHT', 4, 1000, 2000, '遥远的太古过去赌上主神的宝座跟「武神-日孁」战斗，在死斗之后被封印起来的恶神。为使自己的封印解开而操纵了「日孁」，产生出不祥的「天照」给世界带来了黑暗，但他的野心在「倭」等年轻武神的活跃之下最终破灭了。'),
(9418365, 'Bujin Hirume', '武神-日孁', '武神－ヒルメ', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 4, 2000, 1000, '这张卡不能通常召唤。把「武神-日孁」以外的自己墓地1只名字带有「武神」的怪兽从游戏中除外的场合可以特殊召唤。此外，这个方法特殊召唤的这张卡被对方破坏送去墓地的场合才能发动。自己丢弃1张手卡。那之后，对方选1张手卡丢弃。「武神-日孁」在自己场上只能有1只表侧表示存在。'),
(92586237, 'Bujin Mahitotsu', '武神-目一箇', '武神－マヒトツ', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 4, NULL, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把1张其他的「武神」卡送去墓地才能发动。这张卡从手卡特殊召唤。 ②：可以从以下效果选择1个发动。 ●从手卡把1只「武神」怪兽送去墓地才能发动。从自己墓地选和那只怪兽卡名不同的1只「武神」怪兽加入手卡。 ●从自己墓地把1只「武神」怪兽除外才能发动。和那只怪兽卡名不同的1只「武神」怪兽从卡组送去墓地。'),
(53678698, 'Bujin Mikazuchi', '武神-御雷', '武神－ミカヅチ', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 4, 1900, 1500, '自己场上的名字带有「武神」的兽战士族怪兽被战斗或者卡的效果破坏送去墓地时，这张卡可以从手卡特殊召唤。此外，这张卡在场上表侧表示存在，从自己手卡有名字带有「武神」的怪兽被送去自己墓地的场合，那个回合的结束阶段时1次，可以从卡组把1张名字带有「武神」的魔法·陷阱卡加入手卡。「武神-御雷」在自己场上只能有1只表侧表示存在。'),
(63049052, 'Bujin Regalia - The Jewel', '玺律的武神', '璽律する武神', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '发动后这张卡变成装备卡，给自己场上1只4阶的超量怪兽装备。装备怪兽的攻击力上升那只怪兽的超量素材数量×300的数值。此外，这个效果让这张卡装备中的场合，1回合1次，可以把手卡1只名字带有「武神」的怪兽在装备怪兽下面重叠作为超量素材。'),
(35183853, 'Bujin Regalia - The Mirror', '镜鸣的武神', '鏡鳴する武神', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有名字带有「武神」的兽战士族怪兽存在，对方场上的怪兽数量比自己场上的怪兽数量多的场合，主要阶段1的开始时才能发动。直到下次的对方回合结束时，双方不能把魔法·陷阱卡的效果发动。'),
(30338466, 'Bujin Regalia - The Sword', '剑现的武神', '剣現する武神', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '可以从以下效果选择1个发动。 ●选择自己墓地1只名字带有「武神」的怪兽加入手卡。 ●选择从游戏中除外的1只自己的名字带有「武神」的怪兽回到墓地。'),
(29981935, 'Bujin Torifune', '武神-鸟船', '武神－トリフネ', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 4, 1500, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡解放才能发动。除「武神-鸟船」外的2只种族不同的「武神」怪兽从卡组守备表示特殊召唤。 ②：这张卡在墓地存在，自己对「武神」超量怪兽的超量召唤成功时才能发动。这张卡当作装备卡使用给那只怪兽装备。装备怪兽战斗破坏的怪兽不去墓地而除外。'),
(32339440, 'Bujin Yamato', '武神-倭', '武神－ヤマト', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 4, 1800, 200, '①：「武神-倭」在自己场上只能有1只表侧表示存在。 ②：自己结束阶段才能发动。从卡组把1只「武神」怪兽加入手卡。那之后，选自己1张手卡送去墓地。'),
(68045685, 'Bujincandescence', '武神篱', '武神籬', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己场上的兽战士族「武神」怪兽在战斗阶段以外不会被对方的效果破坏。 ②：1回合1次，从手卡以及自己场上的表侧表示怪兽之中把1只「武神」怪兽送去墓地，以对方场上1张表侧表示的卡为对象才能发动。那张卡的效果直到回合结束时无效。 ③：自己结束阶段，把魔法与陷阱区域的表侧表示的这张卡送去墓地，以自己墓地1只「武神」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(73906480, 'Bujincarnation', '武神降临', '武神降臨', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '对方场上有怪兽存在，自己场上没有怪兽存在的场合，选择自己墓地1只名字带有「武神」的怪兽和从游戏中除外的1只自己的名字带有「武神」的怪兽才能发动。选择的2只怪兽特殊召唤。把这个效果特殊召唤的怪兽作为超量召唤的素材的场合，不是兽族·兽战士族·鸟兽族怪兽的超量召唤不能使用。'),
(11221418, 'Bujincident', '武神隐', '武神隠', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上1只名字带有「武神」的超量怪兽才能发动。选择的怪兽除外，场上的怪兽全部回到手卡。直到发动后第2次的自己的结束阶段时，双方不能召唤·反转召唤·特殊召唤，双方受到的全部伤害变成0。此外，发动后第2次的自己的结束阶段时发动。这张卡的效果除外的怪兽特殊召唤，选择自己墓地1只名字带有「武神」的怪兽在那只特殊召唤的怪兽下面重叠作为超量素材。'),
(66727115, 'Bujinfidel', '武神逐', '武神逐', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上1只名字带有「武神」的兽战士族怪兽解放才能发动。从自己墓地选择和那只怪兽的卡名不同的1只名字带有「武神」的怪兽特殊召唤。'),
(42551040, 'Bujingi Boar', '武神器-生', '武神器－イクタ', 'Effect Monster', 'Beast', 'LIGHT', 4, 1100, 1900, '自己的主要阶段时，自己场上有名字带有「武神」的怪兽存在的场合，把墓地的这张卡从游戏中除外，选择对方场上表侧攻击表示存在的1只怪兽才能发动。选择的怪兽变成表侧守备表示，那个守备力直到结束阶段时变成0。'),
(88940154, 'Bujingi Centipede', '武神器-蜂', '武神器－ハチ', 'Effect Monster', 'Beast', 'LIGHT', 4, 1700, 500, '自己的主要阶段时，自己场上有名字带有「武神」的兽战士族怪兽存在的场合，把墓地的这张卡从游戏中除外才能发动。选择对方场上1张魔法·陷阱卡破坏。「武神器-蜂」的效果1回合只能使用1次。'),
(68601507, 'Bujingi Crane', '武神器-羽羽斩', '武神器－ハバキリ', 'Effect Monster', 'Winged Beast', 'LIGHT', 4, 1600, 300, '①：自己的兽战士族「武神」怪兽和对方怪兽进行战斗的伤害计算时把这张卡从手卡送去墓地才能发动。那只进行战斗的自己怪兽的攻击力只在那次伤害计算时变成原本攻击力的2倍。'),
(89662736, 'Bujingi Crow', '武神器-八咫', '武神器－ヤタ', 'Effect Monster', 'Winged Beast', 'LIGHT', 4, 1700, 800, '自己场上的名字带有「武神」的兽战士族怪兽被选择作为对方怪兽的攻击对象时，把这张卡从手卡送去墓地才能发动。攻击怪兽的攻击无效，给与对方基本分那只怪兽的攻击力一半数值的伤害。「武神器-八咫」的效果1回合只能使用1次。'),
(23857661, 'Bujingi Fox', '武神器-冲津', '武神器－オキツ', 'Effect Monster', 'Beast', 'LIGHT', 4, 200, 2100, '把墓地的这张卡从游戏中除外，从手卡把1只名字带有「武神」的怪兽送去墓地才能发动。这个回合，自己受到的全部伤害变成0。这个效果在对方回合也能发动。'),
(59251766, 'Bujingi Hare', '武神器-品', '武神器－サグサ', 'Effect Monster', 'Beast', 'LIGHT', 4, 1700, 500, '把墓地的这张卡从游戏中除外，选择自己场上1只名字带有「武神」的兽战士族怪兽才能发动。选择的怪兽在这个回合只有1次不会被战斗以及卡的效果破坏。这个效果在对方回合也能发动。「武神器-品」的效果1回合只能使用1次。'),
(16157341, 'Bujingi Ibis', '武神器-尾羽张', '武神器－オハバリ', 'Effect Monster', 'Winged Beast', 'LIGHT', 4, 1600, 300, '自己的主要阶段1，把这张卡从手卡送去墓地，选择自己场上1只名字带有「武神」的怪兽才能发动。这个回合，选择的怪兽向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(94096616, 'Bujingi Ophidian', '武神器-蛇', '武神器－オロチ', 'Effect Monster', 'Winged Beast', 'LIGHT', 4, 1700, 500, '自己的主要阶段1，把这张卡从手卡送去墓地，选择自己场上1只名字带有「武神」的怪兽才能发动。这个回合，选择的怪兽可以直接攻击对方玩家。'),
(10860121, 'Bujingi Pavo', '武神器-五百箇', '武神器－イオツミ', 'Effect Monster', 'Winged Beast', 'LIGHT', 4, 1700, 800, '「武神器-五百箇」的效果1回合只能使用1次。 ①：自己场上的兽战士族「武神」怪兽被战斗破坏送去墓地时，把这张卡从手卡送去墓地才能发动。从卡组把1只「武神」怪兽特殊召唤。'),
(50474354, 'Bujingi Peacock', '武神器-八尺琼', '武神器－ヤサカニ', 'Effect Monster', 'Winged Beast', 'LIGHT', 4, 1800, 700, '自己的主要阶段2，把这张卡从手卡送去墓地才能发动。从卡组把1只名字带有「武神」的怪兽加入手卡。这个效果发动的回合，自己不能把名字带有「武神」的卡以外的魔法·陷阱·效果怪兽的效果发动。「武神器-八尺琼」的效果1回合只能使用1次。'),
(69723159, 'Bujingi Quilin', '武神器-丛云', '武神器－ムラクモ', 'Effect Monster', 'Beast', 'LIGHT', 4, 1600, 900, '自己的主要阶段时，自己场上有名字带有「武神」的兽战士族怪兽存在的场合，把墓地的这张卡从游戏中除外才能发动。选择对方场上表侧表示存在的1张卡破坏。「武神器-丛云」的效果1回合只能使用1次。'),
(11958188, 'Bujingi Raven', '武神器-真经津', '武神器－マフツ', 'Effect Monster', 'Winged Beast', 'LIGHT', 4, 1600, 900, '①：自己场上的「武神」怪兽被和对方怪兽的战斗破坏送去自己墓地时，把这张卡从手卡送去墓地才能发动。那只对方怪兽破坏。'),
(56574543, 'Bujingi Sinyou', '武神器-都牟刈', '武神器－ツムガリ', 'Effect Monster', 'Beast', 'LIGHT', 4, 1500, 1000, '「武神器-都牟刈」的效果1回合只能使用1次。 ①：自己的兽战士族「武神」怪兽和对方怪兽进行战斗的从伤害步骤开始时到伤害计算前，把墓地的这张卡除外才能发动。那只进行战斗的自己怪兽的攻击力直到伤害步骤结束时上升进行战斗的对方怪兽的攻击力数值，那次战斗给与对方的战斗伤害变成一半。'),
(86868952, 'Bujingi Swallow', '武神器-八握', '武神器－ヤツカ', 'Effect Monster', 'Winged Beast', 'LIGHT', 4, 1700, 800, '自己的主要阶段1，把这张卡从手卡送去墓地，选择自己场上1只名字带有「武神」的怪兽才能发动。这个回合，选择的怪兽在同1次的战斗阶段中可以作2次攻击。这个效果发动的回合，选择的怪兽以外的怪兽不能攻击。'),
(5818294, 'Bujingi Turtle', '武神器-边津', '武神器－ヘツカ', 'Effect Monster', 'Beast', 'LIGHT', 4, 1700, 1200, '①：自己场上的「武神」怪兽为对象的魔法·陷阱·怪兽的效果发动时，把墓地的这张卡除外才能发动。那个效果无效。'),
(80555062, 'Bujingi Warg', '武神器-道返', '武神器－チカヘシ', 'Effect Monster', 'Beast', 'LIGHT', 4, 1200, 1900, '①：只要这张卡在怪兽区域守备表示存在，这张卡以外的自己场上的「武神」怪兽不会被效果破坏。'),
(32202803, 'Bujingi Wolf', '武神器-足', '武神器－タルタ', 'Effect Monster', 'Beast', 'LIGHT', 4, 1100, 2000, '只要这张卡在场上表侧表示存在，这张卡以外的自己场上的兽族·兽战士族·鸟兽族怪兽不会被战斗破坏。'),
(71095768, 'Bujinki Ahashima', '武神姬-淡岛', '武神姫－アハシマ', 'Link Monster', 'Beast-Warrior', 'LIGHT', NULL, 1500, NULL, '相同等级的怪兽2只 这个卡名的①②的效果1回合各能使用1次。这张卡不能作为连接素材。 ①：这张卡连接召唤成功的场合才能发动。相同等级的怪兽从手卡以及自己墓地各选1只效果无效特殊召唤，只用那2只为素材把1只超量怪兽超量召唤。 ②：这张卡所连接区的超量怪兽把超量素材取除来让效果发动的场合，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(68618157, 'Bujinki Amaterasu', '武神姬-天照', '武神姫－アマテラス', 'XYZ Monster', 'Beast-Warrior', 'LIGHT', 4, 2600, 2500, '4星怪兽×3 ①：「武神姬-天照」在自己场上只能有1只表侧表示存在。 ②：自己·对方回合1次，把这张卡1个超量素材取除，以除外的1只自己的4星以下的怪兽为对象才能发动。发动回合的以下效果适用。 ●自己回合：作为对象的怪兽特殊召唤。 ●对方回合：作为对象的怪兽加入手卡。'),
(1855932, 'Bujintei Kagutsuchi', '武尊神帝－迦具土', '武神帝－カグツチ', 'XYZ Monster', 'Beast-Warrior', 'LIGHT', 4, 2500, 2000, '兽战士族4星怪兽×2 这张卡超量召唤成功时，从自己卡组上面把5张卡送去墓地。这张卡的攻击力上升这个效果送去墓地的名字带有「武神」的卡数量×100的数值。此外，自己场上的名字带有「武神」的兽战士族怪兽被战斗或者卡的效果破坏的场合，可以作为那1只破坏的怪兽的代替而把这张卡1个超量素材取除。「武神帝-迦具土」在自己场上只能有1只表侧表示存在。'),
(75840616, 'Bujintei Susanowo', '武神帝-须佐之男', '武神帝－スサノヲ', 'XYZ Monster', 'Beast-Warrior', 'LIGHT', 4, 2400, 1600, '4星「武神」怪兽×2 ①：「武神帝-须佐之男」在自己场上只能有1只表侧表示存在。 ②：这张卡可以向对方怪兽全部各作1次攻击。 ③：1回合1次，把这张卡1个超量素材取除才能发动。从卡组选1只「武神」怪兽加入手卡或送去墓地。'),
(73289035, 'Bujintei Tsukuyomi', '武尊神帝－月读', '武神帝－ツクヨミ', 'XYZ Monster', 'Beast-Warrior', 'LIGHT', 4, 1800, 2300, '光属性4星怪兽×2 1回合1次，把这张卡1个超量素材取除才能发动。手卡全部送去墓地，从卡组抽2张卡。此外，这张卡因对方的卡的效果从场上离开时，可以从自己墓地选择最多有那个时候这张卡持有的超量素材数量的4星的名字带有「武神」的兽战士族怪兽特殊召唤。「武神帝-月读」在自己场上只能有1只表侧表示存在。'),
(55599882, 'Bujintervention', '武神决战', '武神決戦', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择场上1只名字带有「武神」的怪兽才能发动。这个回合选择的怪兽战斗破坏持有那只怪兽的原本攻击力以上的攻击力的怪兽的场合，破坏的那只怪兽除外，再把那些同名怪兽从对方的手卡·卡组·额外卡组·墓地全部除外。');